/* @autogenerated */
import { Component, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { of, Subject } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { ConfirmDialogService } from '../dialog/confirm-dialog.service';
import { NotifyService } from '../notify/notify.service';
import { ConfirmAction } from './confirm-action';

interface Item {
  uid: string;
  enabled?: boolean;
}

const acl = signal<{ generic: Acl } | undefined>(undefined);
const repository = {
  acl: () => Object.assign(acl, { fetch: jasmine.createSpy('fetch') }) as any,
  deleteByKey: jasmine.createSpy('deleteByKey'),
};

@Component({ selector: 'test-delete-action', template: '' })
class TestDeleteAction extends ConfirmAction<Item> {
  readonly name = 'delete';
  protected readonly scope = 'test';
  protected readonly repository = repository;

  protected execute([item]: Item[]) {
    return this.repository.deleteByKey(item.uid);
  }
}

@Component({ selector: 'test-enable-selection-action', template: '' })
class TestEnableSelectionAction extends ConfirmAction<Item> {
  readonly name = 'enableSelection';
  override readonly multiple = true;
  protected readonly scope = 'test';
  protected readonly repository = repository;

  protected override get permission() {
    return 'enable';
  }

  protected override appliesTo(items: Item[]) {
    return items.every((item) => !item.enabled);
  }

  protected execute() {
    return of(undefined);
  }
}

describe('ConfirmAction', () => {
  let confirm: jasmine.SpyObj<ConfirmDialogService>;
  let notify: jasmine.SpyObj<NotifyService>;

  const create = <T>(type: new (...args: any[]) => T) => {
    const fixture = TestBed.createComponent(type);
    fixture.detectChanges();
    return fixture.componentInstance;
  };

  beforeEach(() => {
    acl.set(undefined);
    repository.deleteByKey.calls.reset();
    confirm = jasmine.createSpyObj<ConfirmDialogService>('ConfirmDialogService', ['confirm']);
    notify = jasmine.createSpyObj<NotifyService>('NotifyService', ['success']);
    TestBed.configureTestingModule({
      imports: [
        TestDeleteAction,
        TestEnableSelectionAction,
        TranslocoTestingModule.forRoot({
          langs: {
            en: { common: { action: { delete: { label: 'Delete', icon: 'delete', report: 'Deleted' } } } },
            'test/en': { action: { delete: { label: 'Delete test', content: 'Sure?' } } },
          },
          translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
        }),
      ],
      providers: [
        { provide: ConfirmDialogService, useValue: confirm },
        { provide: NotifyService, useValue: notify },
      ],
    });
  });

  afterEach(() => TestBed.resetTestingModule());

  it('reads texts from the scope with fallback to common.action', () => {
    const action = create(TestDeleteAction);

    expect(action.label()).toBe('Delete test');
    expect(action.icon()).toBe('delete');
    expect(action.tooltip()).toBe('');
  });

  it('is visible only when the ACL allows its permission', () => {
    const action = create(TestDeleteAction);
    expect(action.visible([])()).toBeFalse();

    acl.set({ generic: { allows: [{ name: 'delete', allowed: true }] } });
    expect(action.visible([])()).toBeTrue();
  });

  it('combines a custom permission with appliesTo', () => {
    const action = create(TestEnableSelectionAction);
    acl.set({ generic: { allows: [{ name: 'enable', allowed: true }] } });

    expect(action.visible([{ uid: '1' }])()).toBeTrue();
    expect(action.visible([{ uid: '1', enabled: true }])()).toBeFalse();
  });

  it('confirms, executes, notifies and closes the container', () => {
    confirm.confirm.and.returnValue(of(true));
    repository.deleteByKey.and.returnValue(of(undefined));
    const action = create(TestDeleteAction);
    const container = jasmine.createSpyObj('ActionContainerComponent', ['close']);
    action.container.set(container);
    action.selection = signal([{ uid: 'a' }]);

    action.run();

    expect(confirm.confirm).toHaveBeenCalledWith({
      messageKey: 'test.action.delete.content',
      titleKey: undefined,
      okKey: undefined,
      cancelKey: undefined,
    });
    expect(repository.deleteByKey).toHaveBeenCalledWith('a');
    expect(notify.success).toHaveBeenCalledWith('common.action.delete.report', undefined, undefined);
    expect(container.close).toHaveBeenCalled();
  });

  it('only closes the container when the user cancels', () => {
    confirm.confirm.and.returnValue(of(false));
    const action = create(TestDeleteAction);
    const container = jasmine.createSpyObj('ActionContainerComponent', ['close']);
    action.container.set(container);

    action.run();

    expect(repository.deleteByKey).not.toHaveBeenCalled();
    expect(notify.success).not.toHaveBeenCalled();
    expect(container.close).toHaveBeenCalled();
  });

  it('drops the pending confirmation when destroyed', () => {
    const answer = new Subject<boolean>();
    confirm.confirm.and.returnValue(answer);
    const fixture = TestBed.createComponent(TestDeleteAction);
    fixture.detectChanges();

    fixture.componentInstance.run();
    fixture.destroy();

    expect(answer.observed).toBeFalse();
  });
});
